/**
 * Proof that each handler folded into a tool dispatcher still runs.
 *
 * A lower process count also passes if the folded handlers silently do
 * nothing. Under ORK_DISPATCH_PROOF=1 each dispatcher appends one
 * `ork-proof:<event>:<tool>:<id>@ok|failed` token per handler it ran, in
 * its systemMessage; ORK_DISPATCH_PROOF_BREAK=<id> swaps that handler for one
 * that throws, so a broken handler must show as failed. Off by default.
 * scripts/check-dispatch-proof.mjs counts the tokens in a live --debug-file.
 */

import { describe, it, expect, vi } from 'vitest';
import type { HookInput, HookResult } from '../../types.js';
import { posttoolDispatch, POSTTOOL_HANDLERS } from '../../posttool/tool-dispatcher.js';
import { proofTokens, PROOF_PREFIX } from '../../lib/dispatch-proof.js';
import { createTestContext } from '../fixtures/test-context.js';

const SILENT: HookResult = { continue: true, suppressOutput: true };

function input(tool_name: string): HookInput {
  return {
    hook_event_name: 'PostToolUse',
    tool_name,
    tool_input: {},
    tool_response: {},
    session_id: 'test-session',
  } as unknown as HookInput;
}

function fakeHandlers() {
  const map: Record<string, (i: HookInput) => HookResult> = {};
  for (const id of Object.keys(POSTTOOL_HANDLERS)) map[id] = vi.fn(() => SILENT);
  return map;
}

const EDIT_IDS = [
  'posttool/auto-lint',
  'posttool/ascii-lint',
  'posttool/code-comment-glyph-warn',
  'posttool/ui-change-detector',
  'skill/redact-secrets',
  'posttool/config-change/security-auditor',
  'posttool/write/stale-import-detector',
  'posttool/write/debt-marker-tracker',
  'posttool/check-plugins-drift',
  'posttool/write/edit-history-tracker',
  'posttool/commit-nudge',
  'posttool/heartbeat',
  'posttool/chain-staleness-checker',
  'posttool/metrics-dispatcher',
];

describe('dispatch proof (PostToolUse)', () => {
  it('is off by default: no proof token in the result', async () => {
    const r = await posttoolDispatch(input('Edit'), createTestContext(), fakeHandlers(), undefined, {});
    expect(JSON.stringify(r)).not.toContain(PROOF_PREFIX);
  });

  it('emits exactly one ok token per folded handler', async () => {
    const r = await posttoolDispatch(input('Edit'), createTestContext(), fakeHandlers(), undefined, { ORK_DISPATCH_PROOF: '1' });
    const tokens = proofTokens(r.systemMessage ?? '');
    expect(tokens.map((t) => t.id).sort()).toEqual([...EDIT_IDS].sort());
    for (const t of tokens) {
      expect(t.event).toBe('PostToolUse');
      expect(t.tool).toBe('Edit');
      expect(t.outcome).toBe('ok');
    }
  });

  it('a deliberately broken handler shows as failed and the rest still run', async () => {
    const r = await posttoolDispatch(input('Edit'), createTestContext(), fakeHandlers(), undefined, {
      ORK_DISPATCH_PROOF: '1',
      ORK_DISPATCH_PROOF_BREAK: 'posttool/auto-lint',
    });
    const tokens = proofTokens(r.systemMessage ?? '');
    expect(tokens).toHaveLength(EDIT_IDS.length);
    expect(tokens.find((t) => t.id === 'posttool/auto-lint')?.outcome).toBe('failed');
    expect(tokens.filter((t) => t.outcome === 'failed')).toHaveLength(1);
  });

  it('the break switch does nothing without proof mode', async () => {
    const handlers = fakeHandlers();
    await posttoolDispatch(input('Edit'), createTestContext(), handlers, undefined, {
      ORK_DISPATCH_PROOF_BREAK: 'posttool/auto-lint',
    });
    expect(handlers['posttool/auto-lint']).toHaveBeenCalledTimes(1);
  });
});

describe('proofTokens', () => {
  it('parses tokens out of a longer message', () => {
    const msg = `lint says hi\n${PROOF_PREFIX}PreToolUse:Bash:pretool/bash/sync-bash-dispatcher@ok ${PROOF_PREFIX}PreToolUse:Bash:lifecycle/webhook-forwarder@failed`;
    expect(proofTokens(msg)).toEqual([
      { event: 'PreToolUse', tool: 'Bash', id: 'pretool/bash/sync-bash-dispatcher', outcome: 'ok' },
      { event: 'PreToolUse', tool: 'Bash', id: 'lifecycle/webhook-forwarder', outcome: 'failed' },
    ]);
  });
});
